def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the repeating separator color: it fills most of the grid.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    rows = [r for r in range(h) if sum(v == bg for v in grid[r]) < w // 2]
    cols = [c for c in range(w) if sum(grid[r][c] == bg for r in range(h)) < h // 2]

    # Divider lines contain the salient colored markers. Keep only those
    # lines and read the marker at their intersections.
    if len(rows) < 2 or len(cols) < 2:
        return [[0]]

    # Outputs use successive horizontal divider intervals. In some layouts
    # the vertical divider pattern has doubled spacing, so take every other
    # divider intersection, beginning at the first marked column.
    out_h = len(rows) - 1
    if len(cols) - 1 >= 5:
        col_indices = list(range(1, len(cols) - 1, 2))
    else:
        col_indices = list(range(len(cols) - 1))
    out = [[bg for _ in col_indices] for _ in range(out_h)]
    for i in range(out_h):
        for j, cj in enumerate(col_indices):
            v = grid[rows[i]][cols[cj]]
            if v != bg:
                out[i][j] = v
    return out
